static NTSTATUS smbXcli_negprot_dispatch_incoming(struct smbXcli_conn *conn,
TALLOC_CTX *tmp_mem,
uint8_t *inbuf)
{
size_t num_pending = talloc_array_length(conn->pending);
struct tevent_req *subreq;
struct smbXcli_req_state *substate;
struct tevent_req *req;
uint32_t protocol_magic;
size_t inbuf_len = smb_len_nbt(inbuf);
if (num_pending != 1) {
return NT_STATUS_INTERNAL_ERROR;
}
if (inbuf_len < 4) {
return NT_STATUS_INVALID_NETWORK_RESPONSE;
}
subreq = conn->pending[0];
substate = tevent_req_data(subreq, struct smbXcli_req_state);
req = tevent_req_callback_data(subreq, struct tevent_req);
protocol_magic = IVAL(inbuf, 4);
switch (protocol_magic) {
case SMB_MAGIC:
tevent_req_set_callback(subreq, smbXcli_negprot_smb1_done, req);
conn->dispatch_incoming = smb1cli_conn_dispatch_incoming;
return smb1cli_conn_dispatch_incoming(conn, tmp_mem, inbuf);
case SMB2_MAGIC:
if (substate->smb2.recv_iov == NULL) {
substate->smb2.recv_iov = substate->smb1.recv_iov;
substate->smb1.recv_iov = NULL;
}
conn->smb2.mid = 1;
conn->smb2.cur_credits = 0;
tevent_req_set_callback(subreq, smbXcli_negprot_smb2_done, req);
conn->dispatch_incoming = smb2cli_conn_dispatch_incoming;
return smb2cli_conn_dispatch_incoming(conn, tmp_mem, inbuf);
}
DEBUG(10, ("Got non-SMB PDU\n"));
return NT_STATUS_INVALID_NETWORK_RESPONSE;
}

rsvg_acquire_data_data (const char *uri,
const char *base_uri,
char **out_mime_type,
gsize *out_len,
GError **error)
{
const char *comma, *start, *end;
char *mime_type;
char *data;
gsize data_len;
gboolean base64 = FALSE;
g_assert (out_len != NULL);
g_assert (strncmp (uri, "data:", 5) == 0);
mime_type = NULL;
start = uri + 5;
comma = strchr (start, ',');
if (comma && comma != start) {
if (comma > start + BASE64_INDICATOR_LEN &&
!g_ascii_strncasecmp (comma - BASE64_INDICATOR_LEN, BASE64_INDICATOR, BASE64_INDICATOR_LEN)) {
end = comma - BASE64_INDICATOR_LEN;
base64 = TRUE;
} else {
end = comma;
}
if (end != start) {
mime_type = uri_decoded_copy (start, end - start);
}
}
if (comma)
start = comma + 1;
if (*start) {
data = uri_decoded_copy (start, strlen (start));
if (base64)
data = (char *) g_base64_decode_inplace (data, &data_len);
else
data_len = strlen (data);
} else {
data = NULL;
data_len = 0;
}
if (out_mime_type)
*out_mime_type = mime_type;
else
g_free (mime_type);
*out_len = data_len;
return data;
}

void FillLargeHeadersString(std::string* str, int size) {
