for (size_t i = 0; i < m_resources.size(); ++i) {
const SerializedResource& resource = m_resources[i];
if (resource.url == kURL && !resource.data->isEmpty()
&& (mime.isNull() || equalIgnoringCase(resource.mimeType, mime)))
return &resource;
}
return nullptr;
}

static char *langFromHashbang(RCore *core, const char *file) {
int fd = r_sandbox_open (file, O_RDONLY, 0);
if (fd != -1) {
char firstLine[128] = {0};
int len = r_sandbox_read (fd, (ut8*)firstLine, sizeof (firstLine) - 1);
firstLine[len] = 0;
if (!strncmp (firstLine, "#!/", 3)) {
char *nl = strchr (firstLine, '\n');
if (nl) {
*nl = 0;
}
nl = strchr (firstLine, ' ');
if (nl) {
*nl = 0;
}
return strdup (firstLine + 2);
}
r_sandbox_close (fd);
}
return NULL;
}

